import{z as d,x as B,o as i,c as A,q as t,j as s,D as r,d as e,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"覆盖索引扫描","description":"","frontmatter":{"title":"覆盖索引扫描","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/covering-index.md","filePath":"cs/covering-index.md","lastUpdated":1791413859000}'),p={name:"cs/covering-index.md"};function c(m,a,h,C,_,D){const n=B("Mermaid");return i(),A("div",null,[a[2]||(a[2]=t('<h1 id="覆盖索引扫描" tabindex="-1">覆盖索引扫描 <a class="header-anchor" href="#覆盖索引扫描" aria-label="Permalink to &quot;覆盖索引扫描&quot;">​</a></h1><div class="epigraph"><p>若查询需要的列都在索引键（或包含列）里，扫描可以停在索引页，不必回表取堆行。</p><footer>—— 据 Ramakrishnan and Gehrke 对索引只扫描；Date 对物理独立性对照</footer></div><p><a href="/cs/views-materialize">上一课</a>把宽接口收成视图或物化。本课不重做维护。缺口是物理访问：B+ 即将在后课展开，但优化器已经需要「覆盖」这一概念——二级索引通常只存键与 rid，回表随机 I/O 很贵。覆盖则叶子上已有投影所需列。页与槽下一课才讲记录布局。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>视图课留下逻辑宽表。执行仍要选访问路径。二级索引查找后用 rid 回堆，等于随机读。若 <code>SELECT</code> 的列是索引键的子集（或引擎支持 INCLUDE 列），索引叶子已是覆盖投影，范围扫描顺序 I/O。缺口是<strong>何时可以不做堆取</strong>，不是 B+ 分裂算法。</p><p><span class="marginnote">覆盖是物理设计：多一列进索引，更新变重、叶子变宽。与物化视图不同，它仍是一种索引，不是另一张用户表。</span></p><p><span class="marginnote">术语翻译：rid（record id）是索引叶子上记的「行住哪儿」的地址条。普通二级索引查完后要拿这个地址跳回堆页把整行取出来——一次一次的随机 I/O；覆盖扫描意味着要读的列就写在索引叶上，连这条「回程路」都省了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计划里出现 Index-Only Scan：过滤与投影都在索引结构上完成。过滤条件最好对准键前缀，否则退化成索引全扫。堆聚簇（主键顺序存行）是另一种「覆盖」亲戚：主键扫描即数据。本课不把每家 DBMS 的 INCLUDE 语法当标准。</p>',9)),(i(),s(l,null,{default:r(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8A%95%E5%BD%B1%E5%88%97%E9%9B%86%E5%90%88%22%5D%20--%3E%20KEY%5B%22%E6%98%AF%E5%90%A6%E5%8C%85%E5%90%AB%E4%BA%8E%E7%B4%A2%E5%BC%95%22%5D%0A%20%20KEY%20--%3E%20ONLY%5B%22%E5%8F%AA%E6%89%AB%E7%B4%A2%E5%BC%95%E5%8F%B6%22%5D%0A%20%20KEY%20--%3E%20HEAP%5B%22rid%20%E5%9B%9E%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("覆盖把"),E("a",{href:"/cs/algebra-reorder"},"选择投影"),e(" 的投影推进存储结构，是谓词下推的列方向版本。语义不变：结果关系相同。代价模型应计入叶子页数而不是堆页数。后课页槽解释 rid 指向什么。")],-1)),(i(),s(l,null,{default:r(()=>[o(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCAN%5B%22%E7%B4%A2%E5%BC%95%E8%8C%83%E5%9B%B4%E6%89%AB%E6%8F%8F%20%E9%A1%BA%E5%BA%8F%20I%2FO%22%5D%20--%3E%20HIT%5B%22%E6%89%80%E9%9C%80%E5%88%97%E9%83%BD%E5%9C%A8%E5%8F%B6%E5%AD%90%E4%B8%8A%3F%22%5D%0A%20%20HIT%20--%20%22%E6%98%AF%20%E8%A6%86%E7%9B%96%22%20--%3E%20ONLY%5B%22Index-Only%20%E5%AE%8C%E6%88%90%20%E4%B8%8D%E5%9B%9E%E8%A1%A8%22%5D%0A%20%20HIT%20--%20%22%E5%90%A6%22%20--%3E%20BACK%5B%22%E6%8C%89%20rid%20%E9%80%90%E8%A1%8C%E5%9B%9E%E5%A0%86%20%E9%9A%8F%E6%9C%BA%20I%2FO%22%5D%0A%20%20ONLY%20--%3E%20RES%5B%22%E5%90%8C%E4%B8%80%E7%BB%93%E6%9E%9C%E5%85%B3%E7%B3%BB%22%5D%0A%20%20BACK%20--%3E%20RES%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">这张图回答「回表贵在哪」：索引叶子按键值有序相邻存放，顺序读很快；回表则是按 rid 跳到堆上乱序的页，一页一行地随机读。磁盘时代一次随机读顶几百次顺序读，这就是覆盖扫描能快几个量级的原因。</span></p><p><span class="marginnote">常见误区：以为给查询用到的每列都建一个单列索引就能覆盖。优化器通常一次只用一个索引，各索引各自给出 rid 再求交集反而更贵；真要覆盖，应建一个把所需列都收进键（或 INCLUDE）的复合索引。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入列存当主干替代。记录在页上如何安放，下一课页与槽。</p><p>后课默认：有的计划可以不回表。行仍是页上的槽化记录。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>覆盖索引避免回表，服务投影子集。</li><li>用空间与更新成本换 I/O。</li><li>页与槽下一课。</li><li>出处：Ramakrishnan and Gehrke；对照 Date 物理独立性。</li></ul>',7))])}const T=d(p,[["render",c]]);export{u as __pageData,T as default};
